#include "flex_vertex_weight_candidate.h"
#include <iostream>
#include <limits>
int main(){try{if(flexVertexWeightCandidate(1,0,0,1,255,0)!=1||flexVertexWeightCandidate(1,0,0,1,0,0)!=0||flexVertexWeightCandidate(1,0,0,1,255,255)!=0||flexVertexWeightCandidate(1,0,0,1,0,255)!=1)throw std::runtime_error("weight endpoint mismatch");for(unsigned s=0;s<256;++s)for(unsigned t=0;t<256;++t){float value=flexVertexWeightCandidate(1,0,0,1,uint8_t(s),uint8_t(t));double speed=s/255.0,side=t/255.0;double expected=speed+(1-2*speed)*side;if(std::abs(value-expected)>2e-7)throw std::runtime_error("weight interpolation mismatch");if(flexVertexWeightCandidate(.25f,.25f,.25f,.25f,uint8_t(s),uint8_t(t))!=.25f)throw std::runtime_error("static weight changed");}bool failed=false;try{flexVertexWeightCandidate(std::numeric_limits<float>::infinity(),0,0,0,0,0);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("nonfinite input accepted");std::cout<<"vertex weight candidate passed 65536 speed_side_pairs endpoints static_inputs nonfinite_rejection native_runtime_oracle=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
